mixin Labelled { String label() => "Practice ready"; }
class Course with Labelled { final String title; Course(this.title); }
void main() { print(Course("HTML").label()); }

mixin Timestamped { DateTime get createdAt => DateTime.now(); }
class Note with Timestamped {}
void main() { print(Note().createdAt); }

mixin Scoring { bool passed(int score) => score >= 50; }
class Assessment with Scoring {}
void main() { print(Assessment().passed(86)); }

mixin Greeting { String greet(String name) => "Welcome, $name"; }
class Mentor with Greeting {}
void main() { print(Mentor().greet("Ama")); }
